#!/usr/bin/env python3
from __future__ import annotations
import base64
import hashlib
import pathlib
import subprocess
import zlib
PATCH_B64 = (
    ""
)
patch = zlib.decompress(base64.b64decode(PATCH_B64))
assert hashlib.sha256(patch).hexdigest() == "047f049f1b3710a3d35d7c176d667c13c3d9b65e25e5a781fdeddcba66fca16a"
root = pathlib.Path(__file__).resolve().parents[3]
subprocess.run(["git", "apply", "--check", "-"], cwd=root, input=patch, check=True)
subprocess.run(["git", "apply", "-"], cwd=root, input=patch, check=True)
print(f"applied {len(patch)} bytes of M1 typed source-support and scope-consumer cutover")
